import os
import re
from collections import defaultdict

REPO = "/bench/repo"

# Data layer: store package tree + proto/gen/store
def is_data_layer(pkg_path):
    """pkg_path is relative path like server/router/api/v1"""
    if pkg_path == "store" or pkg_path.startswith("store/"):
        return True
    if pkg_path.startswith("proto/gen/store"):
        return True
    if pkg_path.startswith("proto/store"):
        return True
    return False

def get_package(rel_path):
    """Convert file path to Go package path (directory)."""
    d = os.path.dirname(rel_path)
    return d if d else "root"

# Persistent entity types defined in store/*.go (main struct types, not Find/Update/Delete variants)
ENTITY_TYPES = [
    "User", "Memo", "Attachment", "IdentityProvider", "Inbox",
    "InstanceSetting", "MemoRelation", "MemoShare", "Reaction",
    "UserIdentity", "UserSetting",
]

# Also track defining paths
DEFINING_PATHS = {}
for et in ENTITY_TYPES:
    for f in os.listdir(os.path.join(REPO, "store")):
        if f.endswith(".go") and not f.endswith("_test.go"):
            fp = os.path.join(REPO, "store", f)
            with open(fp) as fh:
                content = fh.read()
            if re.search(rf'^type {et} struct', content, re.M):
                DEFINING_PATHS[et] = f"store/{f}"
                break

print("=== Defining paths ===")
for et in ENTITY_TYPES:
    print(f"  {et}: {DEFINING_PATHS.get(et, 'NOT FOUND')}")

# Scan all Go files
entity_packages = {et: set() for et in ENTITY_TYPES}
entity_files = {et: defaultdict(list) for et in ENTITY_TYPES}

# Patterns for store.EntityType references
patterns = {et: re.compile(rf'\bstore\.{et}\b') for et in ENTITY_TYPES}

for root, dirs, files in os.walk(REPO):
    # skip .git
    if '.git' in root:
        continue
    for fn in files:
        if not fn.endswith('.go'):
            continue
        full = os.path.join(root, fn)
        rel = os.path.relpath(full, REPO)
        pkg = get_package(rel)
        if is_data_layer(pkg):
            continue
        with open(full) as fh:
            content = fh.read()
        for et, pat in patterns.items():
            if pat.search(content):
                entity_packages[et].add(pkg)
                entity_files[et][pkg].append(rel)

print("\n=== Distinct external package counts (store.EntityType) ===")
ranked = sorted(ENTITY_TYPES, key=lambda e: len(entity_packages[e]), reverse=True)
for et in ranked:
    pkgs = sorted(entity_packages[et])
    print(f"  {et}: {len(pkgs)} packages")
    for p in pkgs[:8]:
        print(f"    - {p}")
    if len(pkgs) > 8:
        print(f"    ... and {len(pkgs)-8} more")

print("\n=== Top 2 ===")
for et in ranked[:2]:
    print(f"  #{ranked.index(et)+1} {et}: ~{len(entity_packages[et])} distinct external packages")
    # representative refs
    for pkg in sorted(entity_packages[et])[:3]:
        refs = entity_files[et][pkg]
        print(f"    ref: {refs[0]}")
